#include <iostream>
#include <vector>

int main() {
    std::vector<int> datos{2, 5};
    if (datos.empty()) {
        std::cout << "Aucune moyenne";
    } else {
        int suma = 0;
        for (int valor : datos) { suma += valor; }
        double media = static_cast<double>(suma) / static_cast<double>(datos.size());
        std::cout << media;
    }
    return 0;
}

